import{_ as T,o as a,c as t,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/GET-DATA-_002fTYPE_003dTXT.md","filePath":"manual-zh/GET-DATA-_002fTYPE_003dTXT.md","lastUpdated":1785684581000}'),E={name:"manual-zh/GET-DATA-_002fTYPE_003dTXT.md"};function o(A,e,n,c,r,_){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h4 id="_9-4-3-文本数据文件" tabindex="-1">9.4.3 文本数据文件 <a class="header-anchor" href="#_9-4-3-文本数据文件" aria-label="Permalink to &quot;9.4.3 文本数据文件&quot;">​</a></h4><pre><code>GET DATA /TYPE=TXT
        /FILE={’file_name’,file_handle}
        [ENCODING=’encoding’]
        [/ARRANGEMENT={DELIMITED,FIXED}]
        [/FIRSTCASE={first_case}]
        [/IMPORTCASES=...]
        …additional subcommands depending on ARRANGEMENT…
</code></pre><p>当指定 TYPE=TXT 时，<code>GET DATA</code> 以分隔或固定列式格式读取数据，很像 DATA LIST（见 <a href="./DATA-LIST">DATA LIST</a>）。</p><p><code>FILE</code> 子命令是必需的。将要读取的文件指定为字符串文件名或（仅限文本数据）文件句柄（见 <a href="./File-Handles">文件句柄</a>）。</p><p><code>ENCODING</code> 子命令指定要读取文件的字符编码。有关支持的编码信息，请参见 <a href="./INSERT">INSERT</a>。</p><p><code>ARRANGEMENT</code> 子命令决定文件的基本格式。DELIMITED（默认设置）指定输入数据中的字段由空格、制表符或其他用户指定的分隔符分隔。FIXED 指定输入数据中的字段出现在个案记录中特定的固定列位置。</p><p>默认情况下，个案从输入文件的第一行开始读取。要跳过输入文件开头的行，请将 <code>FIRSTCASE</code> 设置为要读取的第一行的行号：2 表示跳过第一行，3 表示跳过前两行，依此类推。</p><p><code>IMPORTCASES</code> 出于兼容性被忽略。使用 <code>N OF CASES</code> 限制从文件读取的个案数（见 <a href="./N-OF-CASES">N OF CASES</a>），或使用 <code>SAMPLE</code> 获取个案的随机样本（见 <a href="./SAMPLE">SAMPLE</a>）。</p><p>其余子命令仅适用于下述两种文件排列中的一种。</p><table tabindex="0"><thead><tr><th>• GET DATA /TYPE=TXT /ARRANGEMENT=DELIMITED</th><th></th><th></th></tr></thead><tbody><tr><td>• GET DATA /TYPE=TXT /ARRANGEMENT=FIXED</td><td></td><td></td></tr></tbody></table>`,10)])])}const l=T(E,[["render",o]]);export{S as __pageData,l as default};
